# Uploaded images (banners, products, collections…). In production nginx can serve /media/ directly
# (faster); until then Django serves them, so uploads always show. Off when media is on S3/CDN.
if settings.SERVE_MEDIA:
    from django.urls import re_path
    from django.views.static import serve
    def media(request,path):
        r=serve(request,path,document_root=settings.MEDIA_ROOT);r['Cache-Control']='public, max-age=604800';return r
    urlpatterns+=[re_path(r'^media/(?P<path>.*)$',media)]
